]

# Test transformations
def flip_h(grid):
    return [row[::-1] for row in grid]

def flip_v(grid):
    return grid[::-1]

def flip_both(grid):
    return flip_h(flip_v(grid))

print("Input:")
for r in input_grid:
    print(r)

print("\nFlip H:")
for r in flip_h(input_grid):
    print(r)

print("\nFlip V:")
for r in flip_v(input_grid):
    print(r)

print("\nFlip Both V+H:")
for r in flip_both(input_grid):
    print(r)
